mapper.select:
select * from coupon_template
and name like concat('%', #{name}, '%') and status = #{status}
order by update_time desc, id desc

mapper.update:
update coupon_template
name = #{name}, coupon_type = #{couponType}, threshold_amount = #{thresholdAmount}, discount_amount = #{discountAmount}, discount_rate = #{discountRate}, max_discount_amount = #{maxDiscountAmount}, validity_type = #{validityType}, validity_days = #{validityDays}, valid_start_time = #{validStartTime}, valid_end_time = #{validEndTime}, scope_type = #{scopeType}, scope_data = #{scopeData}, status = #{status}, update_time = current_timestamp, update_user = #{updateUser}
where id = #{id}

mapper.select:
select a.id, a.template_id as templateId, a.name, t.coupon_type as couponType, t.threshold_amount as thresholdAmount, t.discount_amount as discountAmount, t.discount_rate as discountRate, t.max_discount_amount as maxDiscountAmount, t.validity_type as validityType, t.validity_days as validityDays, t.valid_start_time as validStartTime, t.valid_end_time as validEndTime, t.scope_type as scopeType, t.scope_data as scopeData, a.stock_remaining as stockRemaining, a.issued_count as issuedCount, a.used_count as usedCount, a.per_user_limit as perUserLimit, a.start_time as startTime, a.end_time as endTime, a.status as activityStatus from coupon_activity a join coupon_template t on t.id = a.template_id
and a.name like concat('%', #{name}, '%') and a.status = #{status}
order by a.update_time desc, a.id desc

select id, template_id as templateId, name, per_user_limit as perUserLimit,
       start_time as startTime, end_time as endTime, status
from coupon_activity where id = #{id}

mapper.update:
update coupon_activity
name = #{name}, per_user_limit = #{perUserLimit}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, stock_total = #{stockTotal}, stock_remaining = #{stockRemaining}, update_time = current_timestamp, update_user = #{updateUser}
where id = #{id}

mapper.select:
select * from coupon_activity
where id > #{afterId}
order by id asc
limit #{limit}

select * from coupon_claim_record
where status = 0 and id > #{afterId}
order by id asc
limit #{limit}

select id, activity_id as activityId, template_id as templateId, coupon_name_snapshot as couponNameSnapshot, coupon_type_snapshot as couponTypeSnapshot, threshold_amount_snapshot as thresholdAmountSnapshot, discount_amount_snapshot as discountAmountSnapshot, discount_rate_snapshot as discountRateSnapshot, max_discount_amount_snapshot as maxDiscountAmountSnapshot, scope_type_snapshot as scopeTypeSnapshot, scope_data_snapshot as scopeDataSnapshot, case when status = 0 and valid_end_time <= #{now} then 3 else status end as status, acquired_time as acquiredTime, valid_start_time as validStartTime, valid_end_time as validEndTime, locked_order_id as lockedOrderId, used_order_id as usedOrderId, used_time as usedTime from user_coupon where user_id = #{userId}
and (case when status = 0 and valid_end_time <= #{now} then 3 else status end) = #{status}
order by acquired_time desc, id desc

select coupon_name_snapshot as name, coupon_type_snapshot as couponType, threshold_amount_snapshot as thresholdAmount, discount_amount_snapshot as discountAmount, discount_rate_snapshot as discountRate, max_discount_amount_snapshot as maxDiscountAmount, scope_type_snapshot as scopeType, case when status = 0 and valid_end_time <= #{now} then 3 else status end as status, valid_start_time as validStartTime, valid_end_time as validEndTime from user_coupon where user_id = #{userId}
and (case when status = 0 and valid_end_time <= #{now} then 3 else status end) = #{status}
order by acquired_time desc, id desc
